        {(panel === "cr4-path" || panel === "procurement-mix") && (
          <>
            <span className="self-center text-xs font-medium uppercase text-slate-500">
              History
            </span>
            <ControlChip
              active={showCarried}
              onClick={() => setShowCarried(true)}
            >
              Including carried years
            </ControlChip>
            <ControlChip
              active={!showCarried}
              onClick={() => setShowCarried(false)}
            >
              Disclosed only
            </ControlChip>
          </>
        )}
        {panel === "packer-margins" && (
          <>
            <span className="self-center text-xs font-medium uppercase text-slate-500">
              Margin view
            </span>
            <ControlChip
              active={marginLens === "all"}
              onClick={() => setMarginLens("all")}
            >
              Annual + weekly
            </ControlChip>
            <ControlChip
              active={marginLens === "annual"}
              onClick={() => setMarginLens("annual")}
            >
              Annual only
            </ControlChip>
          </>
        )}
      </div>

      {panel === "regional-hhi" && (
        <ChartCard
          title="Regional procurement HHI vs cash negotiated share"
          subtitle={`DOJ/FTC highly-concentrated line ??? ${ANALYTICS.doJHighlyConcentratedLine}. National HHI ${HEADLINE.nationalHhi2021} sits below it; several LMR regions do not.`}
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={regionalData}
                margin={{ top: 8, right: 16, left: 0, bottom: 48 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="region"
                  tick={{ fontSize: 11 }}
                  interval={0}
                  angle={-18}
                  textAnchor="end"
                  height={60}
                />
                <YAxis
                  yAxisId="hhi"
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "HHI",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 11 },
                  }}
                />
                <YAxis
                  yAxisId="cash"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                  unit="%"
                  label={{
                    value: "Cash %",
                    angle: 90,
                    position: "insideRight",
                    style: { fontSize: 11 },
                  }}
                />
                <Tooltip />
                <Legend />
                <Bar
                  yAxisId="hhi"
                  dataKey="hhi"
                  name="Procurement HHI (2021)"
                  fill={COLORS.hhi}
                  radius={[4, 4, 0, 0]}
                />
                <Line
                  yAxisId="cash"
                  type="monotone"
                  dataKey="cash"
                  name="Cash negotiated %"
                  stroke={COLORS.cash}
                  strokeWidth={2.5}
                  dot={{ r: 4 }}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "cr4-path" && (
        <ChartCard
          title="National four-firm share ??? fed cattle vs cows & bulls"
          subtitle={`Steers & heifers rose from ${HEADLINE.cr4Year1980Pct}% (1980) to ${HEADLINE.cr4Mid1990sPct}% (1995) and have plateaued near ${HEADLINE.nationalCr4Pct}%. Cow/bull slaughter stays far less concentrated.`}
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={cr4Data}
                margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                <YAxis
                  domain={[0, 100]}
                  tick={{ fontSize: 11 }}
                  unit="%"
                />
                <Tooltip />
                <Legend />
                <Area
                  type="monotone"
                  dataKey="fedCr4"
                  name="Steers & heifers CR4"
                  fill={COLORS.fed}
                  fillOpacity={0.25}
                  stroke={COLORS.fed}
                  strokeWidth={2.5}
                />
                <Line
                  type="monotone"
                  dataKey="cowCr4"
                  name="Cows & bulls CR4"
                  stroke={COLORS.cow}
                  strokeWidth={2}
                  strokeDasharray="4 4"
                  connectNulls={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "procurement-mix" && (
        <ChartCard
          title="How packers buy fed cattle ??? cash vs formula"
          subtitle="Formulas became the dominant AMA path after ~2010. Thin residual cash markets still set many formula base prices."
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart
                data={PROCUREMENT_MIX.filter(
                  (r) => showCarried || r.confidence === "disclosed",
                )}
                margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="year" tick={{ fontSize: 11 }} />
                <YAxis domain={[0, 100]} tick={{ fontSize: 11 }} unit="%" />
                <Tooltip />
                <Legend />
                <Area
                  type="monotone"
                  dataKey="cashNegotiatedPct"
                  name="Cash negotiated"
                  stackId="1"
                  fill={COLORS.cash}
                  stroke={COLORS.cash}
                />
                <Area
                  type="monotone"
                  dataKey="formulaPct"
                  name="Formula AMA"
                  stackId="1"
                  fill={COLORS.formula}
                  stroke={COLORS.formula}
                />
                <Area
                  type="monotone"
                  dataKey="otherPct"
                  name="Other / forward"
                  stackId="1"
                  fill={COLORS.other}
                  stroke={COLORS.other}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "packer-margins" && (
        <ChartCard
          title="Packer margins through the herd contraction"
          subtitle={`Swing of ${ANALYTICS.marginSwing2023To2025} $/head from 2023 annual to 2025 annual (Sterling Beef Profit Tracker). Negative since ${HEADLINE.marginsNegativeSince}.`}
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={marginData}
                margin={{ top: 8, right: 12, left: 0, bottom: 32 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  dataKey="period"
                  tick={{ fontSize: 11 }}
                  interval={0}
                  angle={-15}
                  textAnchor="end"
                  height={50}
                />
                <YAxis
                  tick={{ fontSize: 11 }}
                  label={{
                    value: "$ / head",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 11 },
                  }}
                />
                <Tooltip />
                <Bar dataKey="margin" name="Packer margin ($/head)" radius={[4, 4, 0, 0]}>
                  {marginData.map((row) => (
                    <Cell key={row.period} fill={row.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "plants-scatter" && (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Slaughter share by plant capacity tier"
            subtitle={`${ANALYTICS.megaPlantCount} plants ???1M head/yr accounted for ${ANALYTICS.megaPlantFedSharePct}% of fed slaughter (2025).`}
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={plantPie}
                    dataKey="value"
                    nameKey="name"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                    label={({ name, value }) => `${name}: ${value}%`}
                  >
                    {plantPie.map((_, i) => (
                      <Cell
                        key={plantPie[i].name}
                        fill={plantColors[i % plantColors.length]}
                      />
                    ))}
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Cash share vs regional HHI"
            subtitle="Higher HHI regions tend to run thinner cash negotiated shares ??? residual discovery on a concentrated buyer map."
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <ScatterChart margin={{ top: 8, right: 12, left: 0, bottom: 8 }}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    type="number"
                    dataKey="hhi"
                    name="HHI"
                    tick={{ fontSize: 11 }}
                    label={{
                      value: "Regional HHI",
                      position: "insideBottom",
                      offset: -2,
                      style: { fontSize: 11 },
                    }}
                  />
                  <YAxis
                    type="number"
                    dataKey="cashPct"
                    name="Cash %"
                    unit="%"
                    tick={{ fontSize: 11 }}
                  />
                  <ZAxis range={[80, 200]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(value: number | string, name: string) => [
                      value,
                      name === "cashPct" ? "Cash %" : name,
                    ]}
                    labelFormatter={(_, payload) =>
                      payload?.[0]?.payload?.region ?? ""
                    }
                  />
                  <Scatter
                    name="LMR regions"
                    data={scatterData}
                    fill={COLORS.accent}
                  />
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

